  const benchable = () => view.zoom === 'week' || view.zoom === 'day';
  /* pieces laid out on the bench: Plan only, so in Do the day stays alone and a stack fans out in the tray */
  const benchOk = () => benchable() && !inToday() && !phoneDay();
