    const tilt = () => { k++; return (((k * 37) % 7) - 3) * 0.011; };
    const nudge = () => (((k * 53) % 5) - 2) * 0.02;
    const piece = (p) => ({ key: 'k:' + p.id, kind: 'brick', label: p.name, sub: M.dur(p.dur), icon: p.icon, cat: p.cat, dur: p.dur, drag: { kind: 'block', id: p.id } });
    const lead = kitLead();
