    const cats = fresh('todos').map((id) => { const t = taskById(id); return t ? t.cat || 'yours' : null; })
      .concat(fresh('blocks').map((id) => { const f = M.findAdd(state, id); return f ? f.add.cat || 'yours' : null; })).filter(Boolean);
    const n = cats.length;
