    if (step === 'parts') { const ok = goalStepOk(d, 'parts'), line = partsWords(d); return Object.assign({ line }, d.edit ? save(!ok) : { gold: ['Done', () => goStepTo('plan'), 'gl-parts-done'], off: !ok }); }
