    glRow(rows, 'sliders', 'Change the plan', g.date ? rhythmWords(g.rhythm).replace(/\.$/, '') : timesWords(g) + ', ' + M.dur((g.rhythm && g.rhythm.chunk) || 45) + ' each', () => openGoalFlow(null, 'rhythm', g.id), 'gl-edit-rhythm');
    p.appendChild(rows);
