      const b = button('', 'c-gs-day' + (list.length ? '' : ' none') + (d === today ? ' today' : '') + (ask ? ' ask' : done ? ' done' : ''), () => { got.glDay = d; got.glAnswer = false; Snd.pick(); renderSide(); });
