    row.appendChild(icon(GOAL_MARK, 9, '#CDCDCD'));
    row.appendChild(el('p', 'c-ah-pw', standWords(g, st) + '.' + (guessHours(g) ? (st.doneMin > 0 ? ' ' + goalHrs(st.doneMin) + ' done.' : '') : ' ' + ofHrs(st.doneMin, st.totalMin) + ' done.')));
