      const tile = el('span', 'c-ts-rt'); tile.appendChild(icon(ic, 8, '#FFFFFF'));
      r.append(tile, el('span', 'c-ts-rn', words), icon(open == null ? 'right' : open ? 'up' : 'down', 7, UI.soft));
