      const g = state.groups.find((x) => x.id === f.group);
      const id = M.newId('t');
      commit(() => { state.tasks.push({ id, name, group: f.group, icon: g ? g.icon : 'check', cat: 'yours', dur: null, due: f.due || null, repeat: null, done: false, steps: [] }); });
      Snd.good();
      noteMove('todo');
