    if (onbMemo.key !== key) { const st = fillBlocks(friendsColor(D.buildState(inp, today)), a); st.settings.hours = OB.hoursFor(a); onbMemo = { key, json: JSON.stringify(st) }; }
    return JSON.parse(onbMemo.json);
