        const x = el('i', 'onb-live-b' + (b.sleep ? ' sleep' : '') + (b.free ? ' free' : '') + (opt.hold ? ' hold' : ''));
        x.style.left = l + '%'; x.style.width = w + '%';
        if (!b.free) x.style.background = lk.base;
