            if (FEEL) { Object.assign(d.float.style, { width: cr.width + 'px', height: cr.height + 'px', transformOrigin: gx + 'px ' + gy + 'px', rotate: '-2deg', scale: '1' }); d.float.classList.add('onb-feel'); }
